    iat: int = Field(default_factory=lambda: int(time.time()))
    sub: str
    tenant_id: str
    doc_type: str = Field(pattern="^(terms_of_service|privacy_policy|lgpd_sensitive_health|financial_mandate)$")
    doc_version: str = Field(min_length=1, max_length=64)
